def analyze_earthquake_data(data: List[Dict], threshold: float) -> Tuple[float, int, Dict]:
    """
    Analyzes earthquake data to compute various statistics.

    Parameters:
        - data (List[Dict]): A list of dictionaries, each representing an earthquake event with at least a "magnitude" key.
        - threshold (float): The magnitude threshold to count significant earthquakes.

    Returns:
        - Tuple[float, int, Dict]: A tuple containing the average magnitude, the count of significant earthquakes, and the largest earthquake event.
    """

    if not data:
        return (0.0, 0, {})

    total_magnitude = 0.0
    significant_count = 0
    largest_magnitude = -float('inf')
    largest_earthquake = {}

    for event in data:
        try:
            magnitude = float(event["magnitude"])
            total_magnitude += magnitude

            if magnitude > threshold:
                significant_count += 1

            if magnitude > largest_magnitude:
                largest_magnitude = magnitude
                largest_earthquake = event
        except (KeyError, ValueError, TypeError):
            # Gracefully skip invalid or missing "magnitude" entries
            continue

    if total_magnitude == 0:
        return (0.0, 0, {})

    average_magnitude = total_magnitude / len(data)
    return (average_magnitude, significant_count, largest_earthquake)
