            lcs.append(str1[i - 1])
            i -= 1
            j -= 1
        elif dp[i - 1][j] > dp[i][j - 1]:
            i -= 1
        else:
            j -= 1

    # Step 4: Return the LCS in reverse order
    return ''.join(reversed(lcs))
