def can_assign_workers_to_tasks(n, m, worker_skills, task_skills):
    if n != m:
        return "NO"

    # Build a bipartite graph: worker -> task
    graph = [[] for _ in range(n)]

    # Create a set for each task's required skills
    required_skills_per_task = [set(task) for task in task_skills]

    # For each worker, check which tasks their skills satisfy
    for i in range(n):
        worker_skill_set = set(worker_skills[i])
        for j in range(m):
            if required_skills_per_task[j].issubset(worker_skill_set):
                graph[i].append(j)

    # Kuhn's algorithm for bipartite matching
    match_to = [-1] * m  # Task -> Worker index
    result = 0

    def dfs(worker, visited):
        for task in graph[worker]:
            if not visited[task]:
                visited[task] = True
                if match_to[task] == -1 or dfs(match_to[task], visited):
                    match_to[task] = worker
                    return True
        return False

    for worker in range(n):
        visited = [False] * m
        if dfs(worker, visited):
            result += 1

    return "YES" if result == m else "NO"
