def min_subway_lines(lines, S, D):
    if S == D:
        return 0  # No need to move

    # Step 1: Build a mapping from station to the list of lines that pass through it
    station_to_lines = defaultdict(list)

    for line_id, stations in enumerate(lines):
        for station in stations:
            station_to_lines[station].append(line_id)

    # Step 2: BFS to find the minimum number of subway lines needed
    visited = set()  # Stores (station, line_used) to avoid re-processing
    queue = deque([(S, -1, 0)])  # (current_station, line_used, line_count)

    while queue:
        current_station, prev_line, lines_used = queue.popleft()

        if current_station == D:
            return lines_used

        if (current_station, prev_line) in visited:
            continue

        visited.add((current_station, prev_line))

        # Get all lines that pass through the current station
        for line_id in station_to_lines[current_station]:
            # Skip the line we just used (to avoid switching back to the same line)
            if line_id == prev_line:
                continue
            # Add all stations in this line to the queue
            for next_station in lines[line_id]:
                queue.append((next_station, line_id, lines_used + 1))

    return -1  # Destination not reachable
