def four_sum(arr, target):
    n = len(arr)
    result = []

    if n < 4:
        return result  # Not enough elements to form a quadruplet

    # Sort the array
    arr.sort()

    # Iterate through the array using two pointers approach
    for i in range(n - 3):
        # Skip duplicate elements for i
        if i > 0 and arr[i] == arr[i - 1]:
            continue

        for j in range(i + 1, n - 2):
            # Skip duplicate elements for j
            if j > i + 1 and arr[j] == arr[j - 1]:
                continue

            # Two pointers from j+1 and end
            left = j + 1
            right = n - 1

            while left < right:
                current_sum = arr[i] + arr[j] + arr[left] + arr[right]

                if current_sum == target:
                    result.append([arr[i], arr[j], arr[left], arr[right]])

                    # Skip duplicates for left
                    while left < right and arr[left] == arr[left + 1]:
                        left += 1
                    # Skip duplicates for right
                    while left < right and arr[right] == arr[right - 1]:
                        right -= 1

                    left += 1
                    right -= 1

                elif current_sum < target:
                    left += 1
                else:
                    right -= 1

    return result
