def find_min_bandwidth(n, m, connections):
    # DSU (Union-Find) data structure
    class DSU:
        def __init__(self, size):
            self.parent = list(range(size + 1))  # 1-based indexing
            self.rank = [0] * (size + 1)

        def find(self, x):
            if self.parent[x] != x:
                self.parent[x] = self.find(self.parent[x])  # Path compression
            return self.parent[x]

        def union(self, x, y):
            x_root = self.find(x)
            y_root = self.find(y)
            if x_root == y_root:
                return False  # Already connected
            # Union by rank
            if self.rank[x_root] < self.rank[y_root]:
                self.parent[x_root] = y_root
            else:
                self.parent[y_root] = x_root
                if self.rank[x_root] == self.rank[y_root]:
                    self.rank[x_root] += 1
            return True

    # Sort the edges by bandwidth
    connections.sort(key=lambda x: x[2])

    dsu = DSU(n)
    total_bandwidth = 0
    edges_used = 0

    for u, v, w in connections:
        if dsu.union(u, v):
            total_bandwidth += w
            edges_used += 1
            if edges_used == n - 1:
                break  # MST is complete

    # Check if all routers are connected
    root = dsu.find(1)
    for i in range(2, n + 1):
        if dsu.find(i) != root:
            return -1

    return total_bandwidth
