def int_divide(decompose: int) -> int:
    # dp[i][j] will store the number of ways to partition 'i' using integers up to 'j'
    dp = [[0] * (decompose + 1) for _ in range(decompose + 1)]

    # Base case: There's 1 way to partition 0
    for j in range(decompose + 1):
        dp[0][j] = 1

    # Fill the dp table
    for i in range(1, decompose + 1):
        for j in range(1, decompose + 1):
            # If j > i, we cannot use j in the partition, so carry forward the value from dp[i][j-1]
            if j > i:
                dp[i][j] = dp[i][j-1]
            else:
                # We can take the value from dp[i][j-1] (not using j) or dp[i-j][j] (using j)
                dp[i][j] = dp[i][j-1] + dp[i-j][j]

    return dp[decompose][decompose]
