def shortest_path(graph: Dict[str, List[Tuple[str, float]]], start: str, target: str) -> Tuple[List[str], float]:
    # Priority queue: (distance, current node, path)
    # We use a heap to always expand the node with the shortest known distance
    pq = [(0, start, [start])]

    # Dictionary to keep track of the shortest distance to each node
    distances = {node: float('inf') for node in graph}
    distances[start] = 0

    # Dictionary to keep track of the previous node for reconstructing the path
    previous = {node: None for node in graph}

    while pq:
        current_dist, current_node, path = heapq.heappop(pq)

        # Skip if we've already found a shorter path
        if current_dist > distances[current_node]:
            continue

        # If we've reached the target, return the path and distance
        if current_node == target:
            return (path, current_dist)

        # Explore neighbors
        for neighbor, weight in graph[current_node]:
            distance = current_dist + weight

            # Only update if we find a shorter path
            if distance < distances[neighbor]:
                distances[neighbor] = distance
                previous[neighbor] = current_node
                heapq.heappush(pq, (distance, neighbor, path + [neighbor]))

    # Fallback (should not be reached per problem constraints)
    return ([start, target], 0.0)
