    for case in test_cases:
        N, P = case
        even_count = 0
        odd_count = 0
        for p in P:
            if p % 2 == 0:
                even_count += 1
            else:
                odd_count += 1
        # Number of groups is the number of non-zero parity groups
        group_count = 0
        if even_count > 0:
            group_count += 1
        if odd_count > 0:
            group_count += 1
        results.append(group_count)
    return results
