def longest_balanced_substring(s):
    count_map = {0: -1}  # Initialize with count 0 at index -1
    balance = 0
    max_length = 0

    for i, char in enumerate(s):
        if char == '1':
            balance += 1
        else:
            balance -= 1

        if balance in count_map:
            max_length = max(max_length, i - count_map[balance])
        else:
            count_map[balance] = i

    return max_length
```

