def unique_paths_with_trees(M, N, park):
    # Initialize a DP table with the same dimensions as the park
    dp = [[0] * N for _ in range(M)]

    # If the starting cell is blocked, no path is possible
    if park[0][0] == 1:
        return 0

    # Base case: Only one way to reach the starting cell
    dp[0][0] = 1

    # Fill the DP table
    for i in range(M):
        for j in range(N):
            if park[i][j] == 1:
                dp[i][j] = 0  # Tree, can't pass through
            else:
                if i > 0:
                    dp[i][j] += dp[i-1][j]  # From above
                if j > 0:
                    dp[i][j] += dp[i][j-1]  # From the left

    return dp[M-1][N-1]
```

