def shift_string(s: str, k: int) -> str:
    result = []
    for char in s:
        if char.islower():
            # Shift lowercase letters
            shifted = chr((ord(char) - ord('a') + k) % 26 + ord('a'))
        elif char.isupper():
            # Shift uppercase letters
            shifted = chr((ord(char) - ord('A') + k) % 26 + ord('A'))
        else:
            # According to problem statement, input contains only alphabetical characters
            shifted = char
        result.append(shifted)
    return ''.join(result)
